  border-radius: 2px;
}

input[type="checkbox"] {
  appearance: none;
  width: 1.5rem;
  height: 1.5rem;
  min-width: 1.5rem;
  min-height: 1.5rem;
  border: 2px solid #5dade2;
  border-radius: 4px;
  background: #162847;
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
  margin-top: 0.25rem;
}

input[type="checkbox"]:hover {
  background: #1a3a5c;
  border-color: #85c1e2;
}

input[type="checkbox"]:focus-visible {
  outline: 2px solid #5dade2;
  outline-offset: 2px;
}

input[type="checkbox"]:checked {
  background: #5dade2;
  border-color: #5dade2;
  position: relative;
}

input[type="checkbox"]:checked::after {
  content: '✓';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
