}

.submit-button:focus-visible {
  outline: 2px solid #5dade2;
  outline-offset: 2px;
}

.submit-button:active {
  transform: scale(0.98);
}

.submit-button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

