    color: #333333;
  }

  input[type="checkbox"] {
    background: #f0f0f0;
    border-color: #3d8ec9;
  }

  input[type="checkbox"]:hover {
    background: #e8e8e8;
  }

  input[type="checkbox"]:checked {
    background: #5dade2;
  }

  .help-text {
    color: #666666;
  }
}

/* Responsive design */
@media (max-width: 600px) {
