const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const htmlPath = path.join(__dirname, 'index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

  await page.setContent(htmlContent, { waitUntil: 'load' });

  // Test 1: Try to submit without checking
  console.log('\nTest 1: Submit without checkbox checked');
  const submitBtn = await page.$('button[type="submit"]');
  await submitBtn.click();

  const errorVis = await page.$('#agree-error:not([hidden])');
  const isInvalid = await page.getAttribute('#agree-terms', 'aria-invalid');
  console.log(`- Error visible: ${errorVis !== null}`);
  console.log(`- aria-invalid set: ${isInvalid}`);

  // Test 2: Check the checkbox
  console.log('\nTest 2: Check the checkbox');
  const checkbox = await page.$('#agree-terms');
  await checkbox.click();

  const isChecked = await page.isChecked('#agree-terms');
  const errorHidden = await page.isHidden('#agree-error');
  console.log(`- Checkbox checked: ${isChecked}`);
  console.log(`- Error hidden: ${errorHidden}`);

  // Test 3: Verify label is interactive
  console.log('\nTest 3: Click label to toggle checkbox');
  const label = await page.$('label[for="agree-terms"]');
  await checkbox.click(); // Uncheck first
  let checkedBefore = await page.isChecked('#agree-terms');
  await label.click();
  let checkedAfter = await page.isChecked('#agree-terms');
  console.log(`- Label click toggles checkbox: ${checkedBefore !== checkedAfter}`);

  // Test 4: Tab order
  console.log('\nTest 4: Keyboard navigation');
  await page.keyboard.press('Tab');
  const focusedId = await page.evaluate(() => document.activeElement.id);
  console.log(`- First Tab stops at: ${focusedId}`);

  // Test 5: Check accessibility tree
  console.log('\nTest 5: Accessibility snapshot');
  const snapshot = await page.accessibility.snapshot();
  const checkboxRole = snapshot.children?.find(c => c.name && c.name.includes('terms'));
  console.log(`- Checkbox has accessible name: ${checkboxRole?.name ? 'Yes' : 'No'}`);
  console.log(`- Checkbox role: ${checkboxRole?.role || 'N/A'}`);

  await browser.close();
  console.log('\n✓ All tests completed');
})();

