  cursor: pointer;
  transition: all 0.2s ease;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.submit-button:hover {
  background: linear-gradient(135deg, #85c1e2 0%, #5dade2 100%);
  box-shadow: 0 4px 12px rgba(93, 173, 226, 0.3);
}

.submit-button:focus-visible {
  outline: 2px solid #5dade2;
  outline-offset: 2px;
}

.submit-button:active {
  transform: scale(0.98);
}

.submit-button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

@media (prefers-contrast: more) {
  input[type="checkbox"] {
    border-width: 3px;
  }

  .submit-button {
    text-decoration: underline;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}

@media (prefers-color-scheme: light) {
  body {
    background: linear-gradient(135deg, #f5f5f5 0%, #e8e8e8 100%);
    color: #333333;
  }

  .container {
    background: #ffffff;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
  }

  h1 {
    color: #1a1a1a;
  }

  label {
    color: #333333;
  }

  input[type="checkbox"] {
    background: #f0f0f0;
    border-color: #3d8ec9;
  }

  input[type="checkbox"]:hover {
    background: #e8e8e8;
  }

  input[type="checkbox"]:checked {
    background: #5dade2;
  }

  .help-text {
    color: #666666;
  }
}

@media (max-width: 600px) {
  .container {
    padding: 1.5rem;
  }

  h1 {
    font-size: 1.5rem;
    margin-bottom: 1.5rem;
  }

  label {
    font-size: 0.95rem;
  }

  input[type="checkbox"] {
    width: 1.375rem;
    height: 1.375rem;
    min-width: 1.375rem;
    min-height: 1.375rem;
  }

  .help-text {
    padding-left: 0;
  }
}

@media (forced-colors: active) {
  input[type="checkbox"] {
    border: 2px solid CanvasText;
    background: Canvas;
  }

  input[type="checkbox"]:checked {
    background: Highlight;
    color: HighlightText;
  }

  .submit-button {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
  }

  a.terms-link {
    color: LinkText;
    text-decoration: underline;
  }
}
  </style>
</head>
<body>
  <main>
    <div class="container">
      <h1>Agree to Terms of Use</h1>

      <form id="consent-form" novalidate>
        <div class="form-field">
          <div class="checkbox-wrapper">
            <input
              id="agree-terms"
              type="checkbox"
              name="agree-terms"
              required
              aria-describedby="agree-help agree-error"
            >
            <label for="agree-terms">
              I agree to the <a href="#terms" class="terms-link">terms of use</a>
              <span aria-hidden="true">*</span>
            </label>
          </div>
          <p id="agree-help" class="help-text">
            Please read and accept our terms to continue.
          </p>
          <p id="agree-error" class="error-text" hidden>
            Error: You must agree to the terms to continue.
          </p>
        </div>

        <button type="submit" class="submit-button">Continue</button>
      </form>
    </div>
  </main>

  <script>
const form = document.getElementById('consent-form');
const checkbox = document.getElementById('agree-terms');
const errorElement = document.getElementById('agree-error');

form.addEventListener('submit', (e) => {
  e.preventDefault();

  if (!checkbox.checked) {
    checkbox.setAttribute('aria-invalid', 'true');
    errorElement.hidden = false;
    checkbox.focus();
  } else {
    checkbox.setAttribute('aria-invalid', 'false');
    errorElement.hidden = true;
    console.log('Form submitted successfully!');
    showSuccessMessage();
  }
});

checkbox.addEventListener('change', () => {
  if (checkbox.checked) {
    checkbox.setAttribute('aria-invalid', 'false');
    errorElement.hidden = true;
  }
});

function showSuccessMessage() {
  const button = form.querySelector('button[type="submit"]');
  const originalText = button.textContent;

  button.textContent = '✓ Agreed';
  button.disabled = true;

  setTimeout(() => {
    button.textContent = originalText;
    button.disabled = false;
    form.reset();
    checkbox.setAttribute('aria-invalid', 'false');
  }, 2000);
}
  </script>
</body>
</html>
